import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int l = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());

        char[][] map = new char[l][];
        int startR = 0, startC = 0;

        for (int r = 0; r < l; r++) {
            map[r] = br.readLine().trim().toCharArray();
            for (int col = 0; col < c; col++) {
                if (map[r][col] == 'o') {
                    startR = r;
                    startC = col;
                }
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        int prevR = -1, prevC = -1;
        int curR = startR, curC = startC;

        while (true) {
            int nextR = -1, nextC = -1;

            for (int d = 0; d < 4; d++) {
                int nr = curR + dr[d];
                int nc = curC + dc[d];

                if (nr < 0 || nr >= l || nc < 0 || nc >= c) continue;
                if (map[nr][nc] != 'H') continue;
                if (nr == prevR && nc == prevC) continue;

                nextR = nr;
                nextC = nc;
                break;
            }

            if (nextR == -1) break;

            prevR = curR;
            prevC = curC;
            curR = nextR;
            curC = nextC;
        }

        System.out.println((curR + 1) + " " + (curC + 1));
    }
}
